import base64
c=open("src/evaluation/evaluator.py",encoding="utf-8").read()
NF=base64.b64decode("").decode("utf-8")
OL=base64.b64decode("").decode("utf-8")
NL=base64.b64decode("").decode("utf-8")
idx=c.rfind("# ================================================================",0,c.find("# Evaluator"))
if idx<0: idx=c.find("# Evaluator")
c2=c[:idx]+NF+c[idx:]
c3=c2.replace(OL,NL,1)
print("NF inserted:",c2!=c,"OL replaced:",c3!=c2)
open("src/evaluation/evaluator.py","w",encoding="utf-8").write(c3)
print("done size:",len(c3))
